'use strict';
// Shared by the commands that write committed, generated files.

const fs = require('node:fs');
const path = require('node:path');

// The first line of every generated file: the command that rebuilds it and
// what it is built from, as a comment in the file's language ('lua', 'guide'
// for guides and TOCs, 'svg'). An XML comment cannot hold "--", so an SVG's
// header names the command without its options.
const COMMENT = { lua: ['-- ', ''], guide: ['# ', ''], svg: ['<!-- ', ' -->'] };

function header(lang, command, sources) {
	const [open, close] = COMMENT[lang] || [];
	if (open === undefined) throw new Error(`generated.header: unknown language "${lang}"`);
	// A forge command is named as it is; the others are this toolchain's subcommands.
	const cmd = command.startsWith('forge ') ? command : `node tools/polestar.js ${command}`;
	const text = `Generated by \`${cmd}\` from ${sources}. Do not edit: rebuild with that command.`;
	if (lang === 'svg' && text.includes('--')) throw new Error(`generated.header: an SVG's header cannot contain "--" (XML comments forbid it): ${text}`);
	return `${open}${text}${close}`;
}

// Writes { name: text } into dir (check = false), or compares them with what
// is there (check = true). Returns the names written, or the names that are
// missing or differ.
function syncFiles(files, dir, { check = false } = {}) {
	if (check) return Object.entries(files).filter(([name, text]) => {
		const file = path.join(dir, name);
		return !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text;
	}).map(([name]) => name);
	fs.mkdirSync(dir, { recursive: true });
	for (const [name, text] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), text);
	return Object.keys(files);
}

// The end of a `<generator> build|check` command: prints what was written, or
// which files are stale (exit 1) with the command that rebuilds them.
function reportSync(files, dir, { check, command }) {
	const names = syncFiles(files, dir, { check });
	if (!check) {
		console.log(`wrote ${names.join(', ')}`);
		return 0;
	}
	for (const name of names) console.error(`${name} is out of date (node tools/polestar.js ${command})`);
	if (!names.length) console.log(`${Object.keys(files).length} files up to date`);
	return names.length ? 1 : 0;
}

module.exports = { header, syncFiles, reportSync };
